@Override
public Object compute(String el) {
    try {
        if (null != envContext && !el.contains("#this")) {
            try {
                Object val = parser.parseExpression(el).getValue(envContext);
                if (null != val) {
                    return val;
                }
            } catch (Exception e) {
                // ignore
            }
        }
        return parser.parseExpression(el).getValue(context);
    } catch (Exception e) {
        if (isStrict) throw e;
        return null;
    }
}
